package openapi

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/heliopsy/tix/internal/wire"
)

// Generated files, relative to the module root.
const (
	SpecFile = "api/openapi.yaml"
	DocsFile = "docs/api.md"
)

// The markers around the generated routes table of docs/api.md.
const (
	BeginRoutes = "<!-- BEGIN ROUTES: generated by `just openapi`, do not edit by hand -->"
	EndRoutes   = "<!-- END ROUTES -->"
)

// Write regenerates the document and the routes table under root.
func Write(root string) error {
	doc, err := Build(root)
	if err != nil {
		return err
	}
	spec, err := Encode(doc)
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(root, SpecFile), spec, 0o644); err != nil { // #nosec G306 -- a public document
		return fmt.Errorf("writing %s: %w", SpecFile, err)
	}
	path := filepath.Join(root, DocsFile)
	md, err := os.ReadFile(path) // #nosec G304 -- a file of this repository
	if err != nil {
		return fmt.Errorf("reading %s: %w", DocsFile, err)
	}
	out, err := Splice(md, RoutesTable(doc))
	if err != nil {
		return err
	}
	return os.WriteFile(path, out, 0o644) // #nosec G306 -- a public document
}

// Splice replaces what lies between the routes markers of a page.
func Splice(md []byte, table string) ([]byte, error) {
	begin := bytes.Index(md, []byte(BeginRoutes))
	end := bytes.Index(md, []byte(EndRoutes))
	if begin < 0 || end < begin {
		return nil, fmt.Errorf("%s has no %q ... %q block", DocsFile, BeginRoutes, EndRoutes)
	}
	var b bytes.Buffer
	b.Write(md[:begin+len(BeginRoutes)])
	b.WriteString("\n" + table)
	b.Write(md[end:])
	return b.Bytes(), nil
}

// RoutesTable renders every route under the API prefix as one row per area,
// the area being the operation's tag.
func RoutesTable(doc map[string]any) string {
	byTag := map[string][]string{}
	paths, _ := doc["paths"].(map[string]any)
	for path, item := range paths {
		if !strings.HasPrefix(path, wire.APIPrefix+"/") {
			continue
		}
		for method, op := range item.(map[string]any) {
			tags, _ := op.(map[string]any)["tags"].([]any)
			if len(tags) == 0 {
				continue
			}
			tag := tags[0].(string)
			byTag[tag] = append(byTag[tag],
				strings.ToUpper(method)+" "+strings.TrimPrefix(path, wire.APIPrefix))
		}
	}
	tags := make([]string, 0, len(byTag))
	for t := range byTag {
		tags = append(tags, t)
	}
	sort.Strings(tags)
	var b strings.Builder
	b.WriteString("| Area | Routes |\n| --- | --- |\n")
	for _, t := range tags {
		routes := byTag[t]
		sort.Slice(routes, func(i, j int) bool {
			mi, pi, _ := strings.Cut(routes[i], " ")
			mj, pj, _ := strings.Cut(routes[j], " ")
			if pi != pj {
				return pi < pj
			}
			return methodRank(mi) < methodRank(mj)
		})
		codes := make([]string, 0, len(routes))
		for _, r := range routes {
			codes = append(codes, "`"+r+"`")
		}
		fmt.Fprintf(&b, "| %s | %s |\n", t, strings.Join(codes, ", "))
	}
	return b.String()
}

// methodRank orders methods the way a reader expects them.
func methodRank(m string) int {
	for i, x := range []string{"GET", "POST", "PUT", "PATCH", "DELETE"} {
		if x == m {
			return i
		}
	}
	return 5
}
